//! 🤝️ Bounded original GPOS pair records and legacy kern pairs preserve genuine captured font bytes.
use super::{FontFace,FontProgress,FontReader};
use semio_framework_value::retirement::{RetireOwned,RetirementCursor};
#[derive(Clone,Copy)]
pub(crate) struct Index{at:usize,glyph:u16,class:bool,format:u16,low:usize,high:usize,value:i32,done:bool}
impl Index{
 pub(crate) fn new(r:FontReader<'_>,at:usize,glyph:u16,class:bool)->Result<Self,String>{
  let format=r.u16(at)?;let mut index=Self{at,glyph,class,format,low:0,high:0,value:if class{0}else{-1},done:false};
  match(class,format){
   (false,1)=>{index.high=usize::from(r.u16(at+2)?);r.range(at+4,index.high*2)?;},
   (false,2)|(true,2)=>{index.high=usize::from(r.u16(at+2)?);r.range(at+4,index.high*6)?;},
   (true,1)=>{let from=r.u16(at+2)?;let count=r.u16(at+4)?;r.range(at+6,usize::from(count)*2)?;if glyph>=from&&glyph-from<count{index.value=i32::from(r.u16(at+6+usize::from(glyph-from)*2)?);}index.done=true;},
   _=>return Err("Unsupported font index format".into()),
  }
  Ok(index)
 }
 pub(crate) fn step(&mut self,r:FontReader<'_>)->Result<bool,String>{
  if self.done{return Ok(true);}
  if self.low==self.high{self.done=true;return Ok(true);}
  let n=(self.low+self.high)/2;
  let(from,to,value)=if self.format==1{let g=r.u16(self.at+4+n*2)?;(g,g,n as i32)}else{let at=self.at+4+n*6;let(from,to,value)=(r.u16(at)?,r.u16(at+2)?,i32::from(r.u16(at+4)?));(from,to,if self.class{value}else{value+i32::from(self.glyph.saturating_sub(from))})};
  if self.glyph<from{self.high=n;}else if self.glyph>to{self.low=n+1;}else{self.value=value;self.done=true;}
  Ok(self.done)
 }
 pub(crate) fn result(&self)->i32{self.value}
}
fn value(r:FontReader<'_>,at:usize,format:u16)->Result<i32,String>{if format&0xff00!=0{return Err("Unsupported font pair value".into());}if format&4==0{return Ok(0);}Ok(i32::from(r.i16(at+(format&3).count_ones()as usize*2)?))}
pub struct FontKerningCursor{face:FontFace,left:u16,right:u16,max_work:u64,byte_pointer:Option<usize>,phase:u8,scripts:usize,features:usize,lookups:usize,count:usize,at:usize,script:usize,fallback:usize,lang:usize,record:usize,record_count:usize,record_at:usize,selected:[u16;32],selected_count:usize,selected_at:usize,lookup:usize,lookup_kind:u16,sub_count:usize,sub_at:usize,sub:usize,format:u16,sizes:[usize;2],formats:[u16;2],probe:Option<Index>,class:i32,low:usize,high:usize,set:usize,flags:u16,total:i32,output:Option<i32>,work:u64,cancelled:bool,failure:Option<String>}
impl RetireOwned for FontKerningCursor{fn retirement(self)->Box<dyn RetirementCursor>{self.failure.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.failure.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
impl FontKerningCursor{
 pub fn new(face:FontFace,left:u16,right:u16,max_work:u64)->Self{let invalid=left>=face.glyphs||right>=face.glyphs||!(1..=1000000000).contains(&max_work);Self{face,left,right,max_work,byte_pointer:None,phase:0,scripts:0,features:0,lookups:0,count:0,at:0,script:0,fallback:0,lang:0,record:0,record_count:0,record_at:0,selected:[0;32],selected_count:0,selected_at:0,lookup:0,lookup_kind:0,sub_count:0,sub_at:0,sub:0,format:0,sizes:[0;2],formats:[0;2],probe:None,class:0,low:0,high:0,set:0,flags:0,total:0,output:None,work:0,cancelled:false,failure:invalid.then(||"Invalid font kerning authority".into())}}
 fn legacy(&mut self,bytes:&[u8])->Result<(),String>{let Some(table)=self.face.kern else{self.output=Some(self.total);self.phase=13;return Ok(());};let r=FontReader::new(bytes,table)?;if r.u16(table.offset)?!=0{return Err("Unsupported legacy font kern table".into());}self.count=usize::from(r.u16(table.offset+2)?);if self.count>128{return Err("Font kern subtable limit exceeded".into());}self.sub=table.offset+4;self.at=0;self.phase=11;Ok(())}
 fn step(&mut self,bytes:&[u8])->Result<(),String>{if bytes.len()!=self.face.byte_length||self.byte_pointer.is_some_and(|pointer|pointer!=bytes.as_ptr()as usize){return Err("Captured font kerning source changed".into());}self.byte_pointer=Some(bytes.as_ptr()as usize);
  if self.phase==0{let Some(table)=self.face.gpos else{return self.legacy(bytes);};let r=FontReader::new(bytes,table)?;if r.u16(table.offset)?!=1{return Err("Unsupported font positioning version".into());}self.scripts=table.offset+usize::from(r.u16(table.offset+4)?);self.features=table.offset+usize::from(r.u16(table.offset+6)?);self.lookups=table.offset+usize::from(r.u16(table.offset+8)?);self.count=usize::from(r.u16(self.scripts)?);if self.count>128{return Err("Font script limit exceeded".into());}self.phase=1;return Ok(());}
  if self.phase==11||self.phase==12{return self.step_legacy(bytes);}
  let r=FontReader::new(bytes,self.face.gpos.ok_or("Font positioning authority missing")?)?;
  match self.phase{
   1=>{if self.at<self.count{let at=self.scripts+2+self.at*6;self.at+=1;let table=self.scripts+usize::from(r.u16(at+4)?);match r.u32(at)?{0x6c61746e=>self.script=table,0x44464c54|0x64666c74=>if self.fallback==0{self.fallback=table},_=>{}}}if self.script!=0||self.at==self.count{let script=if self.script!=0{self.script}else{self.fallback};if script==0{return self.legacy(bytes);}let lang=usize::from(r.u16(script)?);if lang==0{self.output=Some(0);self.phase=13;return Ok(());}self.lang=script+lang;self.record_count=usize::from(r.u16(self.lang+4)?);if self.record_count>128{return Err("Font feature limit exceeded".into());}self.at=0;self.phase=2;}},
   2=>{if self.at>self.record_count{self.selected_at=0;self.phase=4;return Ok(());}let feature=if self.at==self.record_count{r.u16(self.lang+2)?}else{r.u16(self.lang+6+self.at*2)?};self.at+=1;if feature==0xffff{return Ok(());}if feature>=r.u16(self.features)?{return Err("Font feature exceeds directory".into());}let at=self.features+2+usize::from(feature)*6;if r.u32(at)?!=0x6b65726e{return Ok(());}self.record=self.features+usize::from(r.u16(at+4)?);let count=usize::from(r.u16(self.record+2)?);if count>128{return Err("Font feature lookup limit exceeded".into());}self.record_at=0;self.sub_count=count;self.phase=3;},
   3=>{if self.record_at==self.sub_count{self.phase=2;return Ok(());}let index=r.u16(self.record+4+self.record_at*2)?;self.record_at+=1;if index>=r.u16(self.lookups)?{return Err("Font feature lookup exceeds directory".into());}let used=&self.selected[..self.selected_count];if let Err(at)=used.binary_search(&index){if self.selected_count==self.selected.len(){return Err("Font kerning lookup limit exceeded".into());}self.selected.copy_within(at..self.selected_count,at+1);self.selected[at]=index;self.selected_count+=1;}},
   4=>{if self.selected_at==self.selected_count{self.output=Some(self.total);self.phase=13;return Ok(());}let index=usize::from(self.selected[self.selected_at]);self.selected_at+=1;self.lookup=self.lookups+usize::from(r.u16(self.lookups+2+index*2)?);self.lookup_kind=r.u16(self.lookup)?;self.sub_count=usize::from(r.u16(self.lookup+4)?);if self.sub_count>128{return Err("Font lookup subtable limit exceeded".into());}self.sub_at=0;self.phase=5;},
   5=>{if self.sub_at==self.sub_count{self.phase=4;return Ok(());}let mut sub=self.lookup+usize::from(r.u16(self.lookup+6+self.sub_at*2)?);self.sub_at+=1;let mut kind=self.lookup_kind;if kind==9{if r.u16(sub)?!=1{return Err("Unsupported font positioning extension".into());}kind=r.u16(sub+2)?;sub=sub.checked_add(r.u32(sub+4)?as usize).ok_or("Font positioning extension overflow")?;}if kind!=2{return Err("Unsupported font positioning lookup".into());}self.sub=sub;self.format=r.u16(sub)?;if !matches!(self.format,1|2){return Err("Unsupported font pair format".into());}self.formats=[r.u16(sub+4)?,r.u16(sub+6)?];self.sizes=self.formats.map(|format|format.count_ones()as usize*2);self.probe=Some(Index::new(r,sub+usize::from(r.u16(sub+2)?),self.left,false)?);self.phase=6;},
   6=>{if !self.probe.as_mut().unwrap().step(r)?{return Ok(());}let coverage=self.probe.take().unwrap().result();if coverage<0{self.phase=5;return Ok(());}if self.format==1{if coverage>=i32::from(r.u16(self.sub+8)?){return Err("Font pair set exceeds coverage".into());}self.set=self.sub+usize::from(r.u16(self.sub+10+coverage as usize*2)?);self.low=0;self.high=usize::from(r.u16(self.set)?);self.phase=7;}else{self.probe=Some(Index::new(r,self.sub+usize::from(r.u16(self.sub+8)?),self.left,true)?);self.phase=8;}},
   7=>{if self.low==self.high{self.phase=5;return Ok(());}let n=(self.low+self.high)/2;let at=self.set+2+n*(2+self.sizes[0]+self.sizes[1]);let glyph=r.u16(at)?;if self.right<glyph{self.high=n;}else if self.right>glyph{self.low=n+1;}else{self.total=self.total.checked_add(value(r,at+2,self.formats[0])?+value(r,at+2+self.sizes[0],self.formats[1])?).ok_or("Font pair value overflow")?;self.phase=4;}},
   8=>{if !self.probe.as_mut().unwrap().step(r)?{return Ok(());}self.class=self.probe.take().unwrap().result();self.probe=Some(Index::new(r,self.sub+usize::from(r.u16(self.sub+10)?),self.right,true)?);self.phase=9;},
   9=>{if !self.probe.as_mut().unwrap().step(r)?{return Ok(());}let right=self.probe.take().unwrap().result()as usize;let left=self.class as usize;let rows=usize::from(r.u16(self.sub+12)?);let columns=usize::from(r.u16(self.sub+14)?);if left>=rows||right>=columns{return Err("Font pair class exceeds matrix".into());}let at=self.sub+16+(left*columns+right)*(self.sizes[0]+self.sizes[1]);self.total=self.total.checked_add(value(r,at,self.formats[0])?+value(r,at+self.sizes[0],self.formats[1])?).ok_or("Font pair value overflow")?;self.phase=4;},
   _=>return Err("Font kerning stage invalid".into()),
  }Ok(())}
 fn step_legacy(&mut self,bytes:&[u8])->Result<(),String>{let r=FontReader::new(bytes,self.face.kern.ok_or("Font kern authority missing")?)?;match self.phase{
   11=>{if self.at==self.count{self.output=Some(self.total);self.phase=13;return Ok(());}let sub=self.sub;let length=usize::from(r.u16(sub+2)?);self.flags=r.u16(sub+4)?;if length<6{return Err("Invalid font kern subtable length".into());}self.at+=1;self.sub=sub.checked_add(length).ok_or("Font kern subtable overflow")?;if self.flags&1!=0&&self.flags>>8==0{let pairs=usize::from(r.u16(sub+6)?);r.range(sub+14,pairs*6)?;self.set=sub;self.low=0;self.high=pairs;self.phase=12;}},
   _=>{if self.low==self.high{self.phase=11;return Ok(());}let n=(self.low+self.high)/2;let at=self.set+14+n*6;let key=(u32::from(self.left)<<16)|u32::from(self.right);let found=r.u32(at)?;if key<found{self.high=n;}else if key>found{self.low=n+1;}else{let pair=i32::from(r.i16(at+4)?);self.total=if self.flags&8!=0{pair}else{self.total.checked_add(pair).ok_or("Font kern value overflow")?};self.phase=11;}},
  }Ok(())}
 pub fn advance(&mut self,bytes:&[u8],grant:usize)->Result<FontProgress,String>{if grant==0{return Err("Invalid font kerning work grant".into());}if self.cancelled{return Err("Font kerning cancelled".into());}if let Some(error)=&self.failure{return Err(error.clone());}for _ in 0..grant{if self.phase==13{break;}if self.work==self.max_work{self.failure=Some("Font kerning work limit exceeded".into());return Err(self.failure.as_ref().unwrap().clone());}if let Err(error)=self.step(bytes){self.failure=Some(error.clone());return Err(error);}self.work+=1;}Ok(FontProgress{phase:match self.phase{0=>"start",1=>"script",2|3=>"feature",4|5=>"lookup",6=>"coverage",7=>"pairSet",8|9=>"classes",11|12=>"legacy",_=>"complete"},work:self.work,done:self.phase==13})}
 pub fn result(&self)->Result<i32,String>{if self.phase!=13||self.cancelled||self.failure.is_some(){return Err("Font kerning incomplete".into());}Ok(self.output.unwrap())}
 pub fn cancel(&mut self){self.cancelled=true;}
}
